function countSubstrings(s) {
  const isPal = (i, j) => {
    while (i < j) if (s[i++] !== s[j--]) return false;
    return true;
  };
  let count = 0;
  for (let i = 0; i < s.length; i++) {
    for (let j = i; j < s.length; j++) {
      if (isPal(i, j)) count++;              // check s[i..j] from scratch
    }
  }
  return count;
}

