int countSubstrings(String s) {
    int count = 0;
    for (int i = 0; i < s.length(); i++) {
        for (int j = i; j < s.length(); j++) {
            if (isPal(s, i, j)) count++;         // check s[i..j] from scratch
        }
    }
    return count;
}

boolean isPal(String s, int i, int j) {
    while (i < j) if (s.charAt(i++) != s.charAt(j--)) return false;
    return true;
}

bool isPal(const string& s, int i, int j) {
    while (i < j) if (s[i++] != s[j--]) return false;
    return true;
}

int countSubstrings(string s) {
    int count = 0, n = s.size();
    for (int i = 0; i < n; i++) {
        for (int j = i; j < n; j++) {
            if (isPal(s, i, j)) count++;         // check s[i..j] from scratch
        }
    }
    return count;
}

function countSubstrings(s) {
  let count = 0;
  const expand = (left, right) => {          // grow outwards while the ends match
    while (left >= 0 && right < s.length && s[left] === s[right]) {
      count++;                               // s[left..right] is a palindrome
      left--;
      right++;
    }
  };
  for (let center = 0; center < s.length; center++) {
    expand(center, center);                  // odd length: one middle letter
    expand(center, center + 1);              // even length: the gap after it
  }
  return count;
}

int countSubstrings(String s) {
    int count = 0;
    for (int center = 0; center < s.length(); center++) {
        count += expand(s, center, center);      // odd length: one middle letter
        count += expand(s, center, center + 1);  // even length: the gap after it
    }
    return count;
}

int expand(String s, int left, int right) {      // grow outwards while the ends match
    int found = 0;
    while (left >= 0 && right < s.length() && s.charAt(left) == s.charAt(right)) {
        found++;                                 // s[left..right] is a palindrome
        left--;
        right++;
    }
    return found;
}

int expand(const string& s, int left, int right) {   // grow outwards while the ends match
    int found = 0;
    while (left >= 0 && right < (int)s.size() && s[left] == s[right]) {
        found++;                                 // s[left..right] is a palindrome
        left--;
        right++;
    }
    return found;
}

int countSubstrings(string s) {
    int count = 0;
    for (int center = 0; center < (int)s.size(); center++) {
        count += expand(s, center, center);      // odd length: one middle letter
        count += expand(s, center, center + 1);  // even length: the gap after it
    }
    return count;
}
